const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const lakeKariba = ee.Geometry.Polygon([
    [[26.5, -17.8], [28.5, -17.8], [28.5, -16.0], [26.5, -16.0], [26.5, -17.8]]
  ]);

  // 2. Data Acquisition - JRC Global Surface Water Monthly History
  const dec2018 = ee.ImageCollection('JRC/GSW1_3/MonthlyHistory')
    .filterDate('2018-12-01', '2019-01-01')
    .filterBounds(lakeKariba);

  const dec2019 = ee.ImageCollection('JRC/GSW1_3/MonthlyHistory')
    .filterDate('2019-12-01', '2020-01-01')
    .filterBounds(lakeKariba);

  // Check collection sizes
  const count2018 = dec2018.size().getInfo();
  const count2019 = dec2019.size().getInfo();

  console.log(`2018 December Images: ${count2018}`);
  console.log(`2019 December Images: ${count2019}`);

  if (count2018 === 0 || count2019 === 0) {
    console.log("<answer>C1</answer>");
    return;
  }

  // Get the monthly images
  const img2018 = dec2018.first();
  const img2019 = dec2019.first();

  // Water detection: values 2 (permanent water) and 3 (seasonal water)
  const waterMask2018 = img2018.eq(2).or(img2018.eq(3));
  const waterMask2019 = img2019.eq(2).or(img2019.eq(3));

  // Calculate water area for each year
  const waterArea2018 = waterMask2018.reduceRegion({
    reducer: ee.Reducer.sum(),
    geometry: lakeKariba,
    scale: 1000,
    maxPixels: 1e9
  }).get('water').getInfo();

  const waterArea2019 = waterMask2019.reduceRegion({
    reducer: ee.Reducer.sum(),
    geometry: lakeKariba,
    scale: 1000,
    maxPixels: 1e9
  }).get('water').getInfo();

  // Check for valid pixels
  const pixelCount2018 = waterMask2018.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: lakeKariba,
    scale: 1000,
    maxPixels: 1e9
  }).get('water').getInfo();

  const pixelCount2019 = waterMask2019.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: lakeKariba,
    scale: 1000,
    maxPixels: 1e9
  }).get('water').getInfo();

  console.log(`2018 Water Area: ${waterArea2018} (Pixels: ${pixelCount2018})`);
  console.log(`2019 Water Area: ${waterArea2019} (Pixels: ${pixelCount2019})`);

  if (pixelCount2018 === 0 || pixelCount2019 === 0) {
    console.log("<answer>C2</answer>");
    return;
  }

  // Validate results
  if (waterArea2018 === null || waterArea2019 === null || 
      isNaN(waterArea2018) || isNaN(waterArea2019) ||
      waterArea2018 < 0 || waterArea2019 < 0) {
    console.log("<answer>C3</answer>");
    return;
  }

  // Compare water levels - higher water area indicates higher water levels
  const waterHigherIn2019 = waterArea2019 > waterArea2018;

  console.log(`Water area difference: ${waterArea2019 - waterArea2018}`);

  if (waterHigherIn2019) {
    console.log("<answer>A</answer>");
  } else {
    console.log("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
